def nline(items):
    """items: (label, kind, value) kind: 'open'/'closed'; direction 'L'/'R'"""
    w=420;h=62
    def X(x):return 25+(x+5)/10*(w-50)
    s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{items["aria"]}"><title>{items["aria"]}</title>']
    s.append(f'<path d="M10 28H{w-10}" stroke="#334155" stroke-width="1.6"/><path d="M{w-10} 28l-8-4v8Z M10 28l8-4v8Z" fill="#334155"/>')
    for t in range(-4,5):
        s.append(f'<path d="M{X(t):.1f} 23v10" stroke="#334155" stroke-width="1.2"/><text x="{X(t):.1f}" y="50" font-size="11" text-anchor="middle" font-family="sans-serif" fill="#334155">{t}</text>')
    v=items['v'];op=items['open'];d=items['dir']
    x0=X(v)
    if d=='L':s.append(f'<path d="M12 28H{x0:.1f}" stroke="#0891b2" stroke-width="4.5"/>')
    else:s.append(f'<path d="M{x0:.1f} 28H{w-12}" stroke="#0891b2" stroke-width="4.5"/>')
    s.append(f'<circle cx="{x0:.1f}" cy="28" r="5.5" fill="{"#ffffff" if op else "#dc2626"}" stroke="#0f172a" stroke-width="1.8"/>')
    s.append('</svg>')
    return ''.join(s)
def nl(aria,v,op,d):return nline(dict(aria=aria,v=v,open=op,dir=d))
