# Figure 9.2: 2x-5y>=10, the half plane not containing the origin (below the line), strip drawn
def halfplane(w,h,xr,yr,line,shade_below,pts,title,dashed=False,step=1,ystep=None,label=None,lblpos=None):
    xmin,xmax=xr;ymin,ymax=yr
    def X(x):return 20+(x-xmin)/(xmax-xmin)*(w-40)
    def Y(y):return h-20-(y-ymin)/(ymax-ymin)*(h-40)
    s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{title}"><title>{title}</title>']
    # shading polygon
    xs=[xmin,xmax]
    ly=[line(x) for x in xs]
    if shade_below:poly=[(xmin,ly[0]),(xmax,ly[1]),(xmax,ymin),(xmin,ymin)]
    else:poly=[(xmin,ly[0]),(xmax,ly[1]),(xmax,ymax),(xmin,ymax)]
    def clip(p):return (p[0],max(ymin,min(ymax,p[1])))
    poly=[clip(p) for p in poly]
    s.append('<polygon points="'+' '.join(f'{X(a):.1f},{Y(b):.1f}' for a,b in poly)+'" fill="#7dd3fc" opacity="0.55"/>')
    ax=Y(0);ay=X(0)
    s.append(f'<path d="M20 {ax:.1f}H{w-12}M{ay:.1f} {h-12}V12" stroke="#334155" stroke-width="1.5" fill="none"/><path d="M{w-12} {ax:.1f}l-8-4v8Z M{ay:.1f} 12l-4 8h8Z" fill="#334155"/>')
    t=math.ceil(xmin/step)*step
    while t<=xmax+1e-9:
        if abs(t)>1e-9:s.append(f'<text x="{X(t):.1f}" y="{ax+14:.1f}" font-size="9" text-anchor="middle" fill="#334155" font-family="sans-serif">{t:g}</text>')
        t+=step
    ys=ystep or step
    t=math.ceil(ymin/ys)*ys
    while t<=ymax+1e-9:
        if abs(t)>1e-9:s.append(f'<text x="{ay-5:.1f}" y="{Y(t)+3:.1f}" font-size="9" text-anchor="end" fill="#334155" font-family="sans-serif">{t:g}</text>')
        t+=ys
    s.append(f'<path d="M{X(xmin):.1f} {Y(ly[0]):.1f}L{X(xmax):.1f} {Y(ly[1]):.1f}" stroke="#0f172a" stroke-width="2.2" fill="none"{" stroke-dasharray=\"6 5\"" if dashed else ""}/>')
    for x,y,lab,dx,dy in pts:
        s.append(f'<circle cx="{X(x):.1f}" cy="{Y(y):.1f}" r="3" fill="#dc2626"/><text x="{X(x)+dx:.1f}" y="{Y(y)+dy:.1f}" font-size="10" font-family="sans-serif" fill="#0f172a">{lab}</text>')
    s.append(f'<text x="{ay+6:.1f}" y="{ax+12:.1f}" font-size="10" font-family="sans-serif" fill="#0f172a">O</text>')
    if label:s.append(f'<text x="{lblpos[0]}" y="{lblpos[1]}" font-size="11" font-family="sans-serif" fill="#0f172a">{label}</text>')
    s.append('</svg>');return ''.join(s)
